+{
+    public string Id { get; set; } = default!;
+    public string Name { get; set; } = default!;
+    public string Category { get; set; } = default!;
+}
+
+// Breaking change: EF Core 9 removed synchronous Cosmos DB query support.
+// All queries must use async equivalents.
+//
+// BEFORE (EF Core 8 — no longer compiles):
+//   var products = db.Products.ToList();
+//   var first    = db.Products.First();
+//   var count    = db.Products.Count();
+//
+// AFTER (EF Core 9):
+//   var products = await db.Products.ToListAsync();
+//   var first    = await db.Products.FirstAsync();
+//   var count    = await db.Products.CountAsync();
+
+class CosmosQueryService
+{
+    private readonly CosmosContext _db;
+    public CosmosQueryService(CosmosContext db) => _db = db;
+
+    // All Cosmos queries must be async in EF Core 9.
+    public async Task<List<Product>> GetAllAsync()
+        => await _db.Products.ToListAsync();
+
+    public async Task<Product> GetFirstAsync()
+        => await _db.Products.FirstAsync();
+
+    public async Task<int> CountAsync()
+        => await _db.Products.CountAsync();
+}
